#!/bin/bash
# usage: probe.sh <file-containing-markdown-for--e>
# prints block E (5th print) of the executable output
EXE=/workspace/dataset/test19_executable
out=$("$EXE" --a '' --b '' --c '' --d '' --e "$(cat "$1")" --f '')
printf '%s' "$out" | awk '
NR<=4{next}
$0=="<h1>Combined Document</h1>"{exit}
{buf=buf $0 "\n"}
END{sub(/\n\n$/,"\n",buf); printf "%s", buf}'

