import fs from 'node:fs';
import zlib from 'node:zlib';

const buf = fs.readFileSync('/workspace/dataset/test19_executable');
const outDir = '/tmp/pyz';
fs.mkdirSync(outDir, { recursive: true });
let n = 0, ok = 0;
for (let i = 0; i < buf.length - 2; i++) {
  if (buf[i] === 0x78 && buf[i + 1] === 0x9c) {
    n++;
    try {
      const res = zlib.inflateSync(buf.subarray(i));
      ok++;
      fs.writeFileSync(`${outDir}/s${i.toString(16)}_${res.length}`, res);
    } catch (e) { /* not a valid stream */ }
  }
}
console.log(`tried ${n}, inflated ${ok}`);
